#!/usr/bin/env node
/**
 * Copy the FSOT audio episodes into dist after expo export.
 *
 * public/fsot/audio (~340MB of MP3s) is gitignored — generated by
 * fsot-trainer/build_public.py, deployed but never committed — and the
 * export step does not carry it into dist. Every `npm run deploy`
 * therefore shipped the FSOT pages without their audio, and the player
 * got the SPA shell instead of MP3s. This step closes the gap; it runs
 * as part of `npm run build`, after export.
 */
import { cpSync, existsSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SRC = join(ROOT, 'public', 'fsot', 'audio');
const DST = join(ROOT, 'dist', 'fsot', 'audio');

if (!existsSync(SRC)) {
  console.warn('[copy-fsot-audio] public/fsot/audio missing — run fsot-trainer/build_public.py; deploying without audio');
} else {
  cpSync(SRC, DST, { recursive: true });
  console.log(`[copy-fsot-audio] ${readdirSync(DST).length} files -> dist/fsot/audio`);
}
